  /** When set, the form edits this bookmark; otherwise it creates a new one. */
  editing?: Bookmark | null;
  error?: string | null;
  onSubmit: (input: CreateInput) => void;
  onCancelEdit: () => void;
}

function tagsToText(tags: string[]): string {
  return tags.join(", ");
}

function textToTags(text: string): string[] {
