:root {
  --bg: #f7f8fa;
  --card: #ffffff;
  --border: #e2e5ea;
  --text: #1c2024;
  --muted: #6b7280;
  --accent: #2563eb;
  --danger: #dc2626;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.app {
  max-width: 760px;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

.app__header h1 {
  font-size: 1.5rem;
  margin: 0 0 1rem;
}

.bookmark-form {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1rem 1.25rem;
  margin-bottom: 1.25rem;
}

.bookmark-form h2 {
  margin: 0 0 0.75rem;
  font-size: 1.1rem;
}

.bookmark-form label {
  display: block;
  font-size: 0.85rem;
  color: var(--muted);
  margin-bottom: 0.75rem;
}

.bookmark-form input,
.bookmark-form textarea,
.search-bar {
  width: 100%;
  margin-top: 0.25rem;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.95rem;
  color: var(--text);
  background: #fff;
}

.bookmark-form textarea {
  min-height: 3rem;
  resize: vertical;
}

.hint {
  font-weight: normal;
  color: var(--muted);
}

button {
  cursor: pointer;
  border: 1px solid var(--border);
  background: #fff;
  color: var(--text);
  padding: 0.5rem 0.85rem;
  border-radius: 8px;
  font-size: 0.9rem;
}

.form-actions button[type="submit"] {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

button.danger {
  color: var(--danger);
  border-color: #f3c6c6;
}

.form-error {
  color: var(--danger);
  font-size: 0.9rem;
  margin: 0.5rem 0;
}

.controls {
  margin-bottom: 1rem;
}

.tag-filter {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.6rem;
}

.tag-chip {
  font-size: 0.8rem;
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
}

.tag-chip--active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.tag-chip--static {
  cursor: default;
  background: #eef2ff;
  border-color: #dfe6ff;
  color: #3949ab;
}

.tag-count {
  opacity: 0.7;
}

.count {
  color: var(--muted);
  font-size: 0.85rem;
  margin: 0.5rem 0;
}

.bookmark-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.bookmark {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 0.8rem 1rem;
}

.bookmark__main {
  min-width: 0;
}

.bookmark__title {
  display: block;
  font-weight: 600;
  color: var(--text);
  text-decoration: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bookmark__url {
  display: block;
  font-size: 0.8rem;
  color: var(--muted);
  text-decoration: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 42ch;
}

.bookmark__tags {
  display: flex;
  gap: 0.35rem;
  margin-top: 0.4rem;
  flex-wrap: wrap;
}

.bookmark__actions {
  display: flex;
  gap: 0.4rem;
  align-items: flex-start;
  flex-shrink: 0;
}

.empty-state {
  text-align: center;
  color: var(--muted);
  padding: 2.5rem 1rem;
  background: var(--card);
  border: 1px dashed var(--border);
  border-radius: 10px;
}

.duplicate-banner {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  background: #fff7ed;
