:root {
  --bg: #f7f8fa;
  --card: #ffffff;
  --border: #e2e5ea;
  --text: #1c2024;
  --muted: #6b7280;
  --accent: #2563eb;
  --danger: #dc2626;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.app {
  max-width: 760px;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

.app__header h1 {
  font-size: 1.5rem;
  margin: 0 0 1rem;
}

.bookmark-form {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1rem 1.25rem;
  margin-bottom: 1.25rem;
}

.bookmark-form h2 {
  margin: 0 0 0.75rem;
  font-size: 1.1rem;
}

.bookmark-form label {
  display: block;
  font-size: 0.85rem;
  color: var(--muted);
  margin-bottom: 0.75rem;
}

.bookmark-form input,
.bookmark-form textarea,
.search-bar {
  width: 100%;
  margin-top: 0.25rem;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.95rem;
  color: var(--text);
  background: #fff;
}

.bookmark-form textarea {
  min-height: 3rem;
  resize: vertical;
}

.hint {
  font-weight: normal;
  color: var(--muted);
}

button {
  cursor: pointer;
  border: 1px solid var(--border);
  background: #fff;
  color: var(--text);
  padding: 0.5rem 0.85rem;
  border-radius: 8px;
  font-size: 0.9rem;
}

.form-actions button[type="submit"] {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

button.danger {
  color: var(--danger);
  border-color: #f3c6c6;
}

.form-error {
  color: var(--danger);
  font-size: 0.9rem;
  margin: 0.5rem 0;
}

.controls {
  margin-bottom: 1rem;
}

.tag-filter {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.6rem;
}

.tag-chip {
  font-size: 0.8rem;
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
