.tag-chip--active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.tag-chip--static {
  cursor: default;
  background: #eef2ff;
  border-color: #dfe6ff;
  color: #3949ab;
}

.tag-count {
  opacity: 0.7;
}

.count {
  color: var(--muted);
  font-size: 0.85rem;
  margin: 0.5rem 0;
}

.bookmark-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.bookmark {
